using Godot;
using System;
using System.Linq;
using HakutaiKagami.Core.Contracts;
public partial class NewGameRuntime
{
    string TreatyDate(long at)=>DateTime.Parse(Snapshot().EpochDate).AddSeconds(at).ToString("M月d日 H:mm");
    void ShowTreatySupply(){var w=Snapshot();long shown=Session.Revision;var popup=new PopupPanel();AddChild(popup);var panel=new PanelContainer();panel.AddThemeStyleboxOverride("panel",WorkBox("1d2b34","b7a16a",14));popup.AddChild(panel);var scroll=new ScrollContainer{CustomMinimumSize=new(540,430),HorizontalScrollMode=ScrollContainer.ScrollMode.Disabled};panel.AddChild(scroll);var box=new VBoxContainer{CustomMinimumSize=new(510,0)};scroll.AddChild(box);box.AddChild(new Label{Text="条約の預かり米・受取と納入",AutowrapMode=TextServer.AutowrapMode.WordSmart});foreach(var c in TreatySupply.View(w).OrderByDescending(c=>c.Cargo>0)){box.AddChild(new Label{Text=c.Stage+" ／ 携行 "+c.Cargo+"kg ／ 実納入 "+c.Delivered+"kg",AutowrapMode=TextServer.AutowrapMode.WordSmart});if(c.KnownOffer is {} t){box.AddChild(new Label{Text="供与元："+NewGameWorld.SiteName(t.Source.Value)+" → 納入先："+NewGameWorld.SiteName(t.Destination.Value)+" ／ 元の供与量 "+t.Quantity+"kg ／ 期限 "+TreatyDate(t.Until),AutowrapMode=TextServer.AutowrapMode.WordSmart});var amount=new SpinBox{MinValue=1,MaxValue=100,Value=Math.Max(1,c.Cargo>0?c.Cargo:Math.Min(20,t.Quantity)),Step=1,Suffix="kg"};box.AddChild(amount);foreach(var action in new[]{TreatySupplyAction.Pickup,TreatySupplyAction.Deliver,TreatySupplyAction.Return}){var i=new TreatySupplyInput(new("request:supply-ui/"+shown+"/"+action),action,c.Root,(long)amount.Value);var b=new Button{Text=action==TreatySupplyAction.Pickup?"供与元の倉で米を受け取る":action==TreatySupplyAction.Deliver?"原本で指定した家の倉へ米を納める":"供与元の倉へ預かり米を返す"};box.AddChild(b);void Update()=>b.Disabled=!TreatySupply.Can(w,i with{Quantity=(long)amount.Value},Session.PlayerControl);amount.ValueChanged+=_=>Update();Update();b.Pressed+=()=>{Submit(Session.ManageTreatySupply(i with{Quantity=(long)amount.Value},Session.PlayerControl,shown));popup.Hide();Refresh();};}foreach(var site in new[]{t.Source,t.Destination}.Distinct()){var b=new Button{Text=NewGameWorld.SiteName(site.Value)+"へ実際に移動する"};box.AddChild(b);b.Pressed+=()=>{popup.Hide();Submit(Session.Submit(TravelWorld.Move(Snapshot(),"request:supply-trip-ui/"+shown,NewGameWorld.Node(site.Value)),shown));Refresh();};}}var cancel=new TreatySupplyInput(new("request:supply-cancel-ui/"+shown),TreatySupplyAction.Cancel,c.Root);if(TreatySupply.Can(w,cancel,Session.PlayerControl)){var b=new Button{Text="受取取りやめの書状を発送（預かり米は返納）"};box.AddChild(b);b.Pressed+=()=>{Submit(Session.ManageTreatySupply(cancel,Session.PlayerControl,shown));popup.Hide();Refresh();};}}foreach(var paper in w.Treaties?.Supply?.Papers.Where(p=>p.Sender==Session.PlayerControl)??Array.Empty<TreatySupplyPaper>()){var retry=new TreatySupplyInput(new("request:supply-retry-ui/"+shown+"/"+paper.Id),TreatySupplyAction.Resend,paper.Root,Original:paper.Id);if(!TreatySupply.Can(w,retry,Session.PlayerControl))continue;var b=new Button{Text="不達を確認した書状を同じ宛先・元期限で再送"};box.AddChild(b);b.Pressed+=()=>{Submit(Session.ManageTreatySupply(retry,Session.PlayerControl,shown));popup.Hide();Refresh();};}var close=new Button{Text="地図へ戻る"};box.AddChild(close);close.Pressed+=()=>popup.Hide();popup.PopupHide+=()=>popup.QueueFree();popup.PopupCentered(new Vector2I(580,520));}
    void ShowTreatySupplyLetter(EntityId id){var k=Branch(Session.PlayerControl).Knowledge.Messages.Single(m=>m.Id==id);if(k.KnownBody==null)return;var p=ContractJson.Read<TreatySupplyPaper>(System.Text.Encoding.UTF8.GetBytes(k.KnownBody));string line=p.Kind==TreatySupplyPaperKind.Offer?"この数量の実米を家の倉に確保した。本人が現地で受け取り、原本で指定した家の倉へ運んで納めてほしい。受取後も納入までは供与元所有の預かり米として扱う。":p.Kind==TreatySupplyPaperKind.Refusal?"現地の条件から実米を確保できない。要請を受け取ったことと、米を供与できることは別である。":p.Kind==TreatySupplyPaperKind.Cancel?"受取を取りやめる。既に預かった米は元の倉へ実際に戻す。":"先の補給要請について、実物の受取を手配したい。";PresentWork("条約補給の供与返書",line,p.Terms is {} t?NewGameWorld.SiteName(t.Source.Value)+"で "+t.Quantity+"kgを引当 ／ 納入先 "+NewGameWorld.SiteName(t.Destination.Value)+" ／ 期限 "+TreatyDate(t.Until):"発送・回答時点 "+TreatyDate(p.ObservedAt)+" ／ 受取手配期限 "+TreatyDate(p.Deadline)+"。返書で確認した範囲です。",p.Sender,p.Sender,"供与手配の差出人","本人が開封した返書");Choice("supply-handling","受取先と預かり米を確認する",()=>{CloseBottomTalk();ShowTreatySupply();});Choice("supply-map","地図へ戻る",CloseBottomTalk);LayoutBottomTalk();}
}
